// We use the Verus verification framework and the vstd Vec library.
use vstd::prelude::*;

verus! {

    // Given a positive integer n ≥ 1, representing the length in days of a contiguous
    // period in a standard 7-day week with exactly 2 days off per week,
    // compute the minimum and maximum number of days off in any such period
    // of length n, allowing the period to start on any day of the week.
    //
    // For every full week (7 days) we get exactly 2 days off.
    // Let k = n / 7  and  r = n % 7.
    // The extra days (r) can contribute as few as max(0, r−5) days off
    // and as many as min(2, r) days off.
    // Hence the overall
    //   minimum = 2*k + max(0, r-5),
    //   maximum = 2*k + min(2, r).
    //
    // We return a Vec<i8> of length 2, where
    //   result[0] = minimum days off,
    //   result[1] = maximum days off.

    pub fn solve(n: i8) -> Vec<i8>
        requires n >= 1
        ensures  result.len() == 2
              && 0 <= result[0]
              && result[0] <= result[1]
              && result[1] <= n
              // specification equations using integer division and remainder
              && result[0] ==
                   2 * (n / 7)
                   + if n % 7 > 5 { n % 7 - 5 } else { 0 }
              && result[1] ==
                   2 * (n / 7)
                   + if n % 7 < 2 { n % 7 } else { 2 }
    {
        // Number of complete weeks
        let k: i8 = n / 7;
        // Remaining days beyond the full weeks
        let r: i8 = n % 7;
        // Compute the extra days-off contributed by the remaining r days
        let min_extra: i8 = if r > 5 { r - 5 } else { 0 };
        let max_extra: i8 = if r < 2 { r } else { 2 };
        // Total min and max days off
        let min_days_off: i8 = 2 * k + min_extra;
        let max_days_off: i8 = 2 * k + max_extra;

        // Assemble the result vector
        let mut result: Vec<i8> = Vec::new();
        result.push(min_days_off);
        result.push(max_days_off);
        result
    }

} // end verus!